// Separate read-only endpoint; never enters the ingestion queue.
try {
    const api = global.get('historyApi');
    const reply = await api.handle({method:msg.req.method, path:msg.req.path,
        query:msg.req.query, authorization:msg.req.headers.authorization});
    msg.statusCode = reply.status;
    msg.headers = reply.headers;
    msg.payload = reply.body;
} catch (error) {
    node.warn('History API unavailable; check history-access.json and the reader connection.');
    msg.statusCode = 503;
    msg.payload = {error:'History API unavailable; server setup is required.'};
}
return msg;

try {
    const store = global.get('captureQueue');
    if (!store) throw new Error('Configure functionGlobalContext.captureQueue; see SERVER_SETUP.md');
    store.queue().enqueue(msg.payload, msg.topic);
    return {}; // Wake the worker only AFTER the original message is on disk.
} catch (error) {
    node.error('Capture queue write failed: ' + error.message, msg);
    return null;
}

try {
    return global.get('captureQueue').queue().claim();
} catch (error) {
    node.error('Capture queue claim failed: ' + error.message, msg);
    return null;
}

// Outputs: register capture (PostgreSQL), measurement/review update (PostgreSQL).
const assert = (condition, message) => { if (!condition) throw new Error(message); };
const finite = value => typeof value === "number" && Number.isFinite(value);
const optional = (value, minimum) => value === null || (finite(value) && value >= minimum);
const integer = value => Number.isSafeInteger(value) && value >= 0;
function text(value, max) {
    return typeof value === "string" && value.length > 0 && value.length <= max && !/[\x00-\x1f]/.test(value);
}
function ns(value) {
    assert(typeof value === "string" && /^[0-9]+$/.test(value), "Expected decimal nanosecond string");
    const n = BigInt(value);
    assert(n > 0n && n <= 9223372036854775806n, "Timestamp out of Influx range");
    return n;
}
function measurements(m) {
    assert(m && integer(m.revision) && text(m.update_id, 100), "Invalid measurement revision/ID");
    assert(optional(m.weight_g, 0) && optional(m.length_mm, 0), "Invalid part measurements");
}
try {
    const data = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
    if (Array.isArray(data)) {
        throw new Error('Legacy upload retained for reconciliation; drain old desktop spool before cutover');
    }
    assert(data && data.schema_version === 1, "Unsupported metadata schema");
    if (data.kind === "review") {
        assert(text(data.machine_id, 128) && text(data.session_id, 200) && integer(data.cycle_id) && data.cycle_id > 0, "Invalid cycle identity");
        const r = data.review;
        assert(r && integer(r.revision) && r.revision > 0 && text(r.update_id, 100), "Invalid review revision/ID");
        ns(r.updated_at_ns);
        assert(typeof r.excluded === 'boolean' && r.settings && typeof r.settings === 'object' && !Array.isArray(r.settings), "Invalid cycle review");
        for (const [key, value] of Object.entries(r.settings)) {
            assert(['machine_id','material','mold_temperature_c','melt_temperature_c','injection_speed_mm_s'].includes(key), 'Unknown correction field');
            assert(key === 'machine_id' ? (text(value,64) && /^[A-Za-z0-9][A-Za-z0-9_.-]{0,63}$/.test(value)) :
                key === 'material' ? (value === null || text(value,200)) :
                optional(value, key === 'injection_speed_mm_s' ? 0 : -273.15), 'Invalid corrected setting');
        }
        msg.query = "SELECT monitoring.receive_review($1, $2, $3::bigint, $4::jsonb) AS result";
        msg.params = [data.machine_id, data.session_id, data.cycle_id, JSON.stringify(r)];
        return [null, msg];
    }
    measurements(data.measurements);
    if (data.kind === "measurements") {
        assert(text(data.machine_id, 128) && text(data.session_id, 200) && integer(data.cycle_id), "Invalid cycle identity");
        msg.query = "SELECT monitoring.receive_measurements($1, $2, $3::bigint, $4::jsonb) AS result";
        msg.params = [data.machine_id, data.session_id, data.cycle_id, JSON.stringify(data.measurements)];
        return [null, msg];
    }
    assert(data.kind === "capture", "Unknown message kind");
    const c = data.capture;
    assert(c && text(c.machine_id, 128) && text(c.session_id, 200) && integer(c.cycle_id), "Invalid capture identity");
    assert(integer(c.session_cycle) && (c.mode === "cycle" || c.mode === "continuous"), "Invalid acquisition mode");
    assert((c.cycle_id === 0) === (c.mode === "continuous"), "Cycle/mode mismatch");
    assert(["complete", "interrupted"].includes(c.status), "Invalid acquisition status");
    assert(c.material === null || text(c.material, 200), "Invalid material");
    assert(optional(c.mold_temperature_c, -273.15), "Invalid mold setpoint");
    assert(c.melt_temperature_c === undefined || optional(c.melt_temperature_c, -273.15), "Invalid melt setpoint");
    assert(c.injection_speed_mm_s === undefined || optional(c.injection_speed_mm_s, 0), "Invalid speed setpoint");
    assert(c.pressure_settings_bar && typeof c.pressure_settings_bar === "object", "Missing pressure settings");
    for (const [key, value] of Object.entries(c.pressure_settings_bar)) {
        assert(/^[a-z][a-z0-9_]*$/.test(key) && optional(value, 0), "Invalid pressure setting");
    }
    const fields = c.config_snapshot && c.config_snapshot.field_names;
    assert(Array.isArray(fields) && fields.length > 0 && new Set(fields).size === fields.length, "Invalid channel list");
    assert(fields.every(f => /^CH[0-9]+_[A-Za-z0-9_]+$/.test(f)), "Invalid channel field name");
    if (c.signal_peaks !== undefined) {
        assert(c.signal_peaks && Object.keys(c.signal_peaks).length === fields.length &&
            fields.every(f => finite(c.signal_peaks[f])), "Invalid signal peaks");
    }
    assert(Array.isArray(data.samples) && data.samples.length > 0 && c.sample_count === data.samples.length, "Sample count mismatch");
    const first = ns(c.first_time_ns), last = ns(c.last_time_ns), base = ns(c.base_time_ns);
    assert(first <= last, "Invalid capture bounds");
    if (c.trigger_start_ns !== null) ns(c.trigger_start_ns);
    if (c.trigger_end_ns !== null) ns(c.trigger_end_ns);
    const tag = value => value.replace(/\\/g, "\\\\").replace(/([ ,=])/g, "\\$1");
    const prefix = `sensor_data,machine_id=${tag(c.machine_id)},session_id=${tag(c.session_id)} `;
    let previous = null;
    const lines = data.samples.map((r, index) => {
        const stamp = ns(r.timestamp_ns);
        assert(previous === null || stamp > previous, "Duplicate/backward sample timestamp");
        previous = stamp;
        assert(stamp >= first && stamp <= last && stamp >= base, "Sample outside capture bounds");
        assert(r.sample_index === index && finite(r.time_s) && r.time_s >= 0, "Invalid sample index/time");
        assert(finite(r.time_s * 1000) && Math.abs(Number(stamp-base)/1e9-r.time_s) <= 0.0000011,
               "Relative time does not match the capture timestamp");
        assert(Object.keys(r).every(k => fields.includes(k) || ["timestamp_ns", "time_s", "sample_index"].includes(k)), "Unexpected sample field");
        // Existing cycle_num and t_ms fields remain floats; only the new sample_index is integer.
        const values = [`cycle_num=${c.cycle_id}`, `t_ms=${r.time_s * 1000}`, `sample_index=${index}i`];
        for (const field of [...fields].sort()) {
            assert(finite(r[field]), `Missing/non-finite channel ${field}`);
            values.push(`${field}=${r[field]}`);
        }
        return prefix + values.join(",") + " " + r.timestamp_ns;
    });
    assert(data.samples[0].timestamp_ns === c.first_time_ns &&
           data.samples[data.samples.length-1].timestamp_ns === c.last_time_ns, "Manifest bounds mismatch");
    if (c.signal_peaks) {
        for (const field of fields) {
            let peak = -Infinity;
            for (const sample of data.samples) peak = Math.max(peak, sample[field]);
            assert(peak === c.signal_peaks[field], "Signal peak does not match waveform");
        }
    }
    msg.capture = c;
    msg.lineProtocol = lines.join("\n");
    msg.query = "SELECT monitoring.register_capture($1::jsonb, md5($2::text), $3::jsonb) AS fingerprint";
    msg.params = [JSON.stringify(c), msg.lineProtocol, JSON.stringify(data.measurements)];
    delete msg.payload;
    return [msg, null];
} catch (error) {
    msg.ingestPermanent = true;
    node.error(error.message, msg);
    return null;
}

// Continue only after PostgreSQL accepted the immutable manifest and waveform hash.
if (!msg.payload || !msg.payload[0] || !msg.payload[0].fingerprint) {
    node.error("No PostgreSQL capture registration receipt", msg);
    return null;
}
msg.fingerprint = msg.payload[0].fingerprint;
const store = global.get('captureQueue');
if (msg.queueId) store.queue().renew(msg);
msg.writeChunks = store.splitLines(msg.lineProtocol);
msg.chunkIndex = 0;
msg.payload = msg.writeChunks[0];
// Preserve lineProtocol for diagnostics; disk queue holds the original envelope.
delete msg.query;
delete msg.params;
msg.headers = {"Content-Type": "text/plain; charset=utf-8"};
msg.requestTimeout = 30000;
return msg;

// No new client ACK protocol. The server catalog records successful Influx writes.
if (Number(msg.statusCode) !== 204) {
    const status = Number(msg.statusCode);
    msg.ingestPermanent = status >= 400 && status < 500 && status !== 408 && status !== 429;
    node.error(`Influx write failed: HTTP ${msg.statusCode}; ${String(msg.payload).slice(0, 300)}`, msg);
    return null;
}
const store = global.get('captureQueue');
if (msg.queueId) store.queue().renew(msg);
msg.chunkIndex += 1;
if (msg.chunkIndex < msg.writeChunks.length) {
    msg.payload = msg.writeChunks[msg.chunkIndex];
    msg.headers = {"Content-Type": "text/plain; charset=utf-8"};
    delete msg.statusCode;
    return [msg, null];
}
msg.query = "SELECT monitoring.mark_stored($1, $2, $3::bigint, $4) AS stored";
msg.params = [msg.capture.machine_id, msg.capture.session_id, msg.capture.cycle_id, msg.fingerprint];
delete msg.payload;
delete msg.headers;
delete msg.writeChunks;
return [null, msg];

try {
    const result = msg.payload && msg.payload[0];
    if (!result || (result.stored !== true && !['applied', 'replay', 'stale', 'conflict'].includes(result.result))) {
        throw new Error('Missing database completion receipt');
    }
    const q = global.get('captureQueue').queue();
    if (['stale', 'conflict'].includes(result.result)) {
        q.fail(msg, 'Measurement ' + result.result + '; review monitoring.measurement_conflicts', true);
        node.warn('Measurement requires reconciliation: ' + msg.queueId);
    } else q.complete(msg);
    return {};
} catch (error) {
    node.error(error.message, msg);
    return null;
}

const reason = msg.error && msg.error.message || 'Unknown ingestion failure';
try {
    const permanent = msg.ingestPermanent === true ||
        /Conflicting immutable|Overlapping capture|Invalid capture|Invalid measurement|violates .*constraint/.test(reason);
    if (msg.queueId) global.get('captureQueue').queue().fail(msg, reason, permanent);
} catch (error) {
    // Log without another Catch loop. Existing disk work remains for recovery.
    node.warn('Could not update queue failure state: ' + error.message);
}
node.warn(reason + (msg.queueId ? '; retained queue ID ' + msg.queueId : '; check server disk/configuration'));
return msg;
